    const fm = (document.SendForm || { elements: [] });
    const stat = $c.util.getComponent('slc_chgRsnContn1').getValue();
    if (stat === "기타") {
        $c.util.getComponent('ipt_chgRsnContn2').setDisabled(false);
        $c.util.getComponent("ipt_chgRsnContn2").focus();
    } else {
        $c.util.getComponent('ipt_chgRsnContn2').setDisabled(true);
    }
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.setTelNo
 * @author Inswave
 * @date 2026. 09. 29
 * @param pTelNo
 * @returns
 * @hidden N
*/
scwin.setTelNo = function (pTelNo) {
    /* sdd-asis-lifecycle:begin setTelNo — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (pTelNo != null && pTelNo !== '') {
        const pTelNoArr = pTelNo.split('-');
        if (pTelNoArr.length == 3) {
            if (pTelNoArr[0] === "00") {
                $c.util.getComponent('ipt_apctTelNo1').setValue("");
            } else {
                $c.util.getComponent('ipt_apctTelNo1').setValue(pTelNoArr[0]);
            }
            $c.util.getComponent('ipt_apctTelNo2').setValue(pTelNoArr[1]);
            $c.util.getComponent('ipt_apctTelNo3').setValue(pTelNoArr[2]);
        } else {

        }
    }
    /* sdd-asis-lifecycle:end */
};


